test('repro locked stream in Response', async () => {
  const stream = new ReadableStream({
    start(controller) {
      controller.enqueue('foo');
      controller.close();
    }
  });

  new Response(stream);
  expect(() => new Response(stream)).toThrow('disturbed or locked');
});

