function serverResourceForStream(
  stream: ReadableStream,
  headers: Record<string, string> = {},
) {
  let responseSent = false;
  return fetchServerResource(async () => {
    if (responseSent) {
      return new Response(null, { status: 418 });
    }
    responseSent = true;
    return new Response(stream, {
      headers,
    });
  });
}

